begin;
set local role service_role;
do $tests$
declare sid uuid; aid uuid; actor uuid:=gen_random_uuid(); ctx jsonb; content jsonb; quote text; preview jsonb; attempt jsonb; result jsonb; pid uuid; blocked boolean;
 payload jsonb:='{"method":"sendMessage","plain":"QA validated post","html":"QA validated post"}';
begin
 if has_function_privilege('anon','public.editorial_telegram_history()','execute') or has_table_privilege('authenticated','public.telegram_deliveries','select') then raise exception 'Public Telegram access allowed'; end if;
 insert into sources(name,url,tier,source_type) values('QA Telegram source','https://telegram-test.invalid/'||actor,'B','local_media') returning id into sid;
 quote:='QA Telegram fixture '||actor||' Управляющая организация выполняет замену оборудования.';
 insert into articles(source_id,title,url,body,published_at) values(sid,'QA Telegram publication '||actor,'https://telegram-test.invalid/'||actor,repeat(quote||' ',8),'2051-01-01') returning id into aid;
 blocked:=false;begin perform editorial_telegram_preview(aid,'test',987654321,'-100111','-100222',false);exception when others then if sqlerrm like 'DRAFT_APPROVAL_REQUIRED%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Unapproved preview allowed';end if;
 ctx:=editorial_draft_context(aid);
 content:=jsonb_build_object('title','QA Одобренный пост','lead','Источник сообщил о замене общего оборудования.','body',repeat(quote,2),'verification_notes','Проверить источник.','content_kind','practice','facts',jsonb_build_array(jsonb_build_object('claim','Замена оборудования','quote',quote)));
 perform editorial_draft_write(aid,'generate',content,0,ctx->>'source_fingerprint',(ctx->'article'->>'updated_at')::timestamptz,actor,'rusboma@gmail.com');
 perform editorial_draft_write(aid,'approve',null,1,ctx->>'source_fingerprint',(ctx->'article'->>'updated_at')::timestamptz,actor,'rusboma@gmail.com',true);
 preview:=editorial_telegram_preview(aid,'production',987654321,'-100111','-100111',false);
 blocked:=false;begin perform editorial_telegram_claim(aid,'production',987654321,'-100111','-100111',false,preview->>'preview_key',payload,actor,'rusboma@gmail.com');exception when others then if sqlerrm like 'TELEGRAM_TEST_REQUIRED%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Production allowed before test';end if;
 preview:=editorial_telegram_preview(aid,'test',987654321,'-100111','-100222',false);
 blocked:=false;begin perform editorial_telegram_claim(aid,'test',987654321,'-100111','-100222',false,'stale',payload,actor,'rusboma@gmail.com');exception when others then if sqlerrm like 'Conflict%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Stale preview accepted';end if;
 attempt:=editorial_telegram_claim(aid,'test',987654321,'-100111','-100222',false,preview->>'preview_key',payload,actor,'rusboma@gmail.com');
 perform editorial_telegram_finish((attempt->>'id')::uuid,'sent',10,null,null);
 if exists(select 1 from publications where article_id=aid) or (select status from articles where id=aid)<>'approved' then raise exception 'Test changed production state';end if;
 preview:=editorial_telegram_preview(aid,'production',987654321,'-100111','-100111',false);
 attempt:=editorial_telegram_claim(aid,'production',987654321,'-100111','-100111',false,preview->>'preview_key',payload,actor,'rusboma@gmail.com');
 pid:=(attempt->>'publication_id')::uuid;
 blocked:=false;begin perform editorial_telegram_claim(aid,'production',987654321,'-100111','-100111',false,preview->>'preview_key',payload,actor,'rusboma@gmail.com');exception when others then if sqlerrm like 'TELEGRAM_DELIVERY_LOCKED%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Duplicate claim accepted';end if;
 perform editorial_telegram_finish((attempt->>'id')::uuid,'failed',null,'TELEGRAM_RATE_LIMIT',10);
 if (select status from publications where id=pid)<>'rejected' then raise exception 'Definite failure kept manual reservation';end if;
 blocked:=false;begin perform editorial_telegram_preview(aid,'production',987654321,'-100111','-100111',false);exception when others then if sqlerrm like 'TELEGRAM_RETRY_LATER%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Retry-after ignored';end if;
 update telegram_deliveries set retry_after=now()-interval '1 second' where article_id=aid;
 result:=editorial_publication_plan('schedule',aid,null,2,null,now()+interval '2 days',actor,'rusboma@gmail.com');pid:=(result->>'publication_id')::uuid;
 preview:=editorial_telegram_preview(aid,'production',987654321,'-100111','-100111',false);
 attempt:=editorial_telegram_claim(aid,'production',987654321,'-100111','-100111',false,preview->>'preview_key',payload,actor,'rusboma@gmail.com');
 perform editorial_telegram_finish((attempt->>'id')::uuid,'unknown',null,'TELEGRAM_NETWORK',null);
 blocked:=false;begin perform editorial_publication_plan('cancel',null,pid,null,1,null,actor,'rusboma@gmail.com');exception when others then if sqlerrm like 'TELEGRAM_DELIVERY_LOCKED%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Ambiguous send reservation cancelled';end if;
 blocked:=false;begin perform editorial_telegram_preview(aid,'production',987654321,'-100111','-100111',false);exception when others then if sqlerrm like 'TELEGRAM_DELIVERY_LOCKED%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Ambiguous send retried';end if;
 blocked:=false;begin perform editorial_telegram_finish((attempt->>'id')::uuid,'failed',null,'unsafe retry',null);exception when others then if sqlerrm like 'TELEGRAM_DELIVERY_LOCKED%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Ambiguous send unlocked';end if;
 perform editorial_telegram_finish((attempt->>'id')::uuid,'sent',20,null,null);
 perform editorial_telegram_finish((attempt->>'id')::uuid,'sent',20,null,null);
 if (select status from articles where id=aid)<>'published' or not exists(select 1 from publications where id=pid and status='published' and telegram_message_id=20 and scheduled_at is null) then raise exception 'Successful receipt not persisted';end if;
 if (select count(*) from telegram_deliveries where article_id=aid and kind='production' and state='sent')<>1 then raise exception 'Production receipt duplicate';end if;
end $tests$;
rollback;
